// n8n Code-node: Dashboard HTML
// Mode: Run Once for All Items

const DATA_URL = 'http://10.20.236.220:5678/webhook/proxmox-dashboard-data';
const INTERVAL_SECONDS = 10;

// Drempels in procenten. Je kunt CPU en RAM afzonderlijk aanpassen.
const CPU_WARNING = 70;
const CPU_HIGH = 85;
const RAM_WARNING = 70;
const RAM_HIGH = 85;

const token = $input.first().json.token;

if (typeof token !== 'string' || !token) {
  throw new Error('JWT-token ontbreekt. Controleer Dashboard sessie maken.');
}

const settings = JSON.stringify({
  dataUrl: DATA_URL,
  token,
  intervalMs: INTERVAL_SECONDS * 1000,
  limits: {
    cpu: [CPU_WARNING / 100, CPU_HIGH / 100],
    ram: [RAM_WARNING / 100, RAM_HIGH / 100],
  },
})
  .replace(/</g, '\\u003c')
  .replace(/>/g, '\\u003e')
  .replace(/&/g, '\\u0026');

// ── 1. HTML ──────────────────────────────────────────────────────────────

function renderDashboard() {
  return `<!doctype html>
<html lang="nl">
  <head>
    <meta charset="utf-8">
    <meta name="viewport" content="width=device-width, initial-scale=1">
    <title>Proxmox | VM-dashboard</title>
    <style>${styles}</style>
  </head>

  <body>
    <header>
      <div class="wrap brand">
