// ── 3. JavaScript in de browser ──────────────────────────────────────────

function dashboardClient() {
  'use strict';

  const $ = id => document.getElementById(id);
  const cfg = JSON.parse($('dashboard-settings').textContent);
  const seconds = cfg.intervalMs / 1000;
  const frames = [];

  let data = null;
  let selectedId = null;
  let accessToken = cfg.token;
  let timer = null;
  let busy = false;
  let expired = false;

  const valid = n => Number.isFinite(n) && n >= 0;
  const fmt = n => n.toLocaleString('nl-BE', { maximumFractionDigits: 1 });
  const pct = n => valid(n) ? `${fmt(n * 100)}%` : '—';
  const clock = t => new Date(t).toLocaleTimeString('nl-BE');

  const loadSeries = [
    ['CPU', 'cpu', '#bd5428'],
    ['RAM', 'ram', '#167567'],
  ];

  function bytes(n) {
    if (!valid(n)) return '—';
    const units = ['B', 'KiB', 'MiB', 'GiB', 'TiB', 'PiB'];
    let i = 0;
    while (n >= 1024 && i < units.length - 1) {
      n /= 1024;
      i++;
    }
    return `${fmt(n)} ${units[i]}`;
  }

  function uptime(n) {
    if (!valid(n)) return '—';
    return `${Math.floor(n / 86400)}d ${Math.floor(n % 86400 / 3600)}u ${Math.floor(n % 3600 / 60)}m`;
  }

  // Eén functie voor kaarten, tabel, filters en meters:
  // zo krijgt dezelfde meting overal dezelfde kleur en hetzelfde label.
  function level(kind, value) {
    const [warn, high] = cfg.limits[kind];

    if (!valid(value)) {
      return { key: 'unknown', label: 'Geen meting', color: '#63706a', bright: '#acb9b0' };
    }
    if (value >= high) {
      return { key: 'high', label: 'Hoog', color: '#b42318', bright: '#ff837a' };
    }
    if (value >= warn) {
      return { key: 'elevated', label: 'Verhoogd', color: '#945300', bright: '#ffc267' };
    }
    return { key: 'normal', label: 'Normaal', color: '#18715c', bright: '#82d9ab' };
  }

  function stateLabel(s) {
    return ({
      running: 'Actief',
      stopped: 'Gestopt',
      paused: 'Gepauzeerd',
      unknown: 'Onbekend',
    })[s] || s;
  }

  function readVM(vm) {
    const r = vm.runtime || {};
    const i = vm.inventory || {};
    const c = vm.config || {};
    const state = r.status || i.status || 'unknown';
    const running = state === 'running';
    const cpu = r.cpu ?? i.cpu;
    const mem = r.mem ?? i.mem;
    const maxmem = r.maxmem ?? i.maxmem;

    return {
      raw: vm,
      id: vm.vmid,
      name: c.name || vm.name || `VM ${vm.vmid}`,
      node: vm.node,
      state,
      running,
      cpu: running && valid(cpu) ? cpu : null,
      cpus: r.cpus ?? i.maxcpu,
      mem,
      maxmem,
      ram: running && valid(mem) && valid(maxmem) && maxmem > 0
        ? mem / maxmem
        : null,
      uptime: r.uptime ?? i.uptime,
      maxdisk: r.maxdisk ?? i.maxdisk,
      netin: r.netin ?? i.netin,
      netout: r.netout ?? i.netout,
      diskread: r.diskread ?? i.diskread,
      diskwrite: r.diskwrite ?? i.diskwrite,
    };
  }

  // Bewaar maximaal twintig minuten. Bewaar alleen de meetwaarden,
  // niet voor iedere meting een kopie van alle VM-configuraties.
  function remember(vms, t) {
    const old = frames.at(-1);
    const byId = new Map();
    let cpuUsed = 0, cpuMax = 0, ramUsed = 0, ramMax = 0;

    for (const m of vms) {
      const prev = old?.byId.get(m.id);
      const dt = old ? (t - old.t) / 1000 : 0;

      const comparable = prev?.running && m.running
        && prev.node === m.node
        && dt > 0 && dt <= 120
        && !(valid(prev.uptime) && valid(m.uptime) && m.uptime < prev.uptime);

      const point = {
        node: m.node, running: m.running, uptime: m.uptime,
        cpu: m.cpu, ram: m.ram,
      };

      for (const k of ['netin', 'netout', 'diskread', 'diskwrite']) {
        point[k] = m[k];
        point[`${k}Rate`] = comparable && valid(m[k])
          && valid(prev[k]) && m[k] >= prev[k]
          ? (m[k] - prev[k]) / dt
          : null;
      }

      byId.set(m.id, point);

      if (valid(m.cpu) && valid(m.cpus) && m.cpus > 0) {
        cpuUsed += m.cpu * m.cpus;
        cpuMax += m.cpus;
      }
      if (valid(m.ram)) {
        ramUsed += m.mem;
        ramMax += m.maxmem;
      }
    }

    frames.push({
      t, byId, cpuUsed, cpuMax, ramUsed, ramMax,
      cpu: cpuMax ? cpuUsed / cpuMax : null,
      ram: ramMax ? ramUsed / ramMax : null,
    });

    while (frames.length > 1 && frames[0].t < t - 20 * 60_000) {
      frames.shift();
    }
  }

  // ── Herbruikbare UI-elementen ──

  function el(tag, text, cls) {
    const e = document.createElement(tag);
    if (text != null) e.textContent = String(text);
    if (cls) e.className = cls;
    return e;
  }

  function svg(tag, attrs) {
    const e = document.createElementNS('http://www.w3.org/2000/svg', tag);
    for (const [k, v] of Object.entries(attrs)) e.setAttribute(k, String(v));
    return e;
  }

  function button(label, action, cls) {
    const b = el('button', label, cls);
    b.type = 'button';
    b.onclick = action;
    return b;
  }

  function openVM(id) {
    selectedId = id;
    renderDetail();
    $('details').scrollIntoView({ behavior: 'smooth', block: 'start' });
  }

  function segment(value, color) {
    const part = el('span');
    part.style.width = `${100 * Math.max(0, Math.min(1, value))}%`;
    part.style.background = color;
    return part;
  }

  function metricCell(kind, value, foot) {
    const l = level(kind, value);
    const cell = el('td', null, `metric ${l.key}`);
    const label = el('div', null, 'metric-label');
    const track = el('div', null, 'track');

    label.append(el('strong', pct(value)), el('small', l.label));
    track.setAttribute('aria-hidden', 'true');
    track.append(segment(valid(value) ? value : 0, l.color));

    cell.append(label, track);
    if (foot) cell.append(el('small', foot, 'metric-foot'));
    return cell;
  }

  function meter(kind, value, caption, dark = false) {
    const l = level(kind, value);
    const name = kind === 'cpu' ? 'Processor' : 'Geheugen';
    const box = el('article', null, dark ? 'meter' : 'panel meter');

    const g = svg('svg', {
      viewBox: '0 0 108 108',
      role: 'img',
      'aria-label': `${name}: ${pct(value)}, ${l.label}`,
    });

    const ring = {
      cx: 54, cy: 54, r: 44, fill: 'none',
      'stroke-width': 8, pathLength: 100, transform: 'rotate(-90 54 54)',
    };

    g.append(svg('circle', { ...ring, stroke: dark ? '#45675c' : '#dce5dc' }));

    if (valid(value) && value > 0) {
      g.append(svg('circle', {
        ...ring,
        stroke: dark ? l.bright : l.color,
        'stroke-dasharray': `${Math.min(100, value * 100)} 100`,
      }));
    }

    const text = svg('text', { x: 54, y: 59, 'text-anchor': 'middle' });
    text.textContent = pct(value);
    g.append(text);

    const desc = el('div');
    desc.append(el('h3', name), el('p', `${l.label} · ${caption}`, 'meter-caption'));
    box.append(g, desc);
    return box;
  }

  function stat(label, value) {
    const box = el('article', null, 'panel stat');
    box.append(el('span', label), el('strong', value ?? '—'));
    return box;
  }

  function specs(title, rows, empty = 'Geen gegevens beschikbaar.') {
    const box = el('article', null, 'panel');
    const dl = el('dl');

    for (const [key, value] of rows) {
      if (value != null && value !== '') dl.append(el('dt', key), el('dd', value));
    }

    box.append(el('h3', title), dl.childElementCount ? dl : el('p', empty, 'note'));
    return box;
  }

  function balance(title, aName, bName, a, b, color) {
    const box = el('article', null, 'panel');
    const strip = el('div', null, 'strip');
    const axis = el('div', null, 'axis');
    const total = valid(a) && valid(b) ? a + b : null;

    if (total > 0) strip.append(segment(a / total, color), segment(b / total, '#75609d'));

    axis.append(
      el('span', `${aName}: ${total > 0 ? pct(a / total) : '—'}`),
      el('span', `${bName}: ${total > 0 ? pct(b / total) : '—'}`),
    );

    const note = total === null ? 'Wachten op vergelijkbare metingen.'
      : total === 0 ? 'Geen activiteit tijdens dit meetinterval.'
      : 'Verdeling over het laatste meetinterval.';

    box.append(el('h3', title), strip, axis, el('p', note, 'note'));
    return box;
  }

  function chart(title, series, type, id = null) {
    const box = el('article', null, 'panel chart');
    const legend = el('div', null, 'legend');
    const format = v => !valid(v) ? '—' : type === 'pct' ? pct(v) : `${bytes(v)}/s`;

    const lines = series.map(([, key]) => frames.map(f => {
      const point = id === null ? f : f.byId.get(id);
      return point?.[key] ?? null;
    }));

    series.forEach(([label, , color], j) => {
      const item = el('span', null, 'legend-item');
      const dot = el('i', null, 'swatch');
      dot.style.background = color;
      item.append(dot, el('span', `${label}: ${format(lines[j].at(-1))}`));
      legend.append(item);
    });

    box.append(el('h3', title), legend);

    if (!lines.some(line => line.filter(valid).length >= 2)) {
      box.append(el('p', 'Nog te weinig meetpunten voor een grafiek.', 'empty'));
      return box;
    }

    const first = frames[0].t;
    const last = frames.at(-1).t;
    const peak = Math.max(...lines.flat().filter(valid));
    const max = type === 'pct' ? Math.max(1, peak) : Math.max(1, peak * 1.1);
    const x = i => 6 + 508 * (frames[i].t - first) / (last - first);
    const y = v => 84 - 78 * v / max;

    const g = svg('svg', {
      viewBox: '0 0 520 90',
      role: 'img',
      'aria-label': `${title}, van ${clock(first)} tot ${clock(last)}`,
    });

    for (const f of [0, 0.5, 1]) {
      g.append(svg('line', {
        x1: 6, x2: 514, y1: y(max * f), y2: y(max * f),
        stroke: '#d4dfd5', 'stroke-dasharray': '3 5',
      }));
    }

    lines.forEach((line, j) => {
      let path = '';
      const color = series[j][2];

      line.forEach((v, i) => {
        if (!valid(v)) return;
        const linked = i > 0 && valid(line[i - 1]) && frames[i].t - frames[i - 1].t <= 120_000;
        path += `${linked ? 'L' : 'M'}${x(i)} ${y(v)} `;

        if (!linked || i === line.length - 1 || !valid(line[i + 1])) {
          g.append(svg('circle', { cx: x(i), cy: y(v), r: 2.5, fill: color }));
        }
      });

      g.append(svg('path', {
        d: path, fill: 'none', stroke: color, 'stroke-width': 2.5,
        'stroke-linejoin': 'round', 'stroke-dasharray': j ? '6 3' : 'none',
      }));
    });

    const axis = el('div', null, 'axis');
    axis.append(el('span', clock(first)), el('span', `0 – ${format(max)}`), el('span', clock(last)));
    box.append(g, axis);
    return box;
  }

  // ── Vlootoverzicht en waarschuwingen ──

  function focusCard(kind, vms) {
    const title = kind === 'cpu' ? 'Hoogste CPU-belasting' : 'Hoogste RAM-gebruik';
    const measured = vms.filter(m => valid(m[kind]));
    const top = measured.reduce((best, m) => !best || m[kind] > best[kind] ? m : best, null);
    const l = level(kind, top?.[kind]);
    const box = el('article', null, `panel focus ${l.key}`);

    box.append(el('p', `${kind.toUpperCase()} / Aandacht`, 'eyebrow'), el('h3', title));

    if (!top) {
      box.append(el('p', 'Geen actieve VM met een geldige meting.', 'empty'));
      return box;
    }

    const high = measured.filter(m => level(kind, m[kind]).key === 'high').length;
    const elevated = measured.filter(m => level(kind, m[kind]).key === 'elevated').length;
    const capacity = kind === 'ram' ? ` · ${bytes(top.mem)} / ${bytes(top.maxmem)}` : '';

    box.append(
      button(top.name, () => openVM(top.id), 'focus-link'),
      el('p', `${pct(top[kind])} · ${l.label}${capacity}`, 'focus-value'),
      el('p', `VM ${top.id} · ${top.node}`, 'note'),
      el('p', `${high} hoog · ${elevated} verhoogd · ${measured.length} gemeten`, 'note'),
    );

    return box;
  }

  function renderOverview() {
    const vms = data?.vms || [];
    const frame = frames.at(-1);
    const active = vms.filter(m => m.running).length;
    const stopped = vms.filter(m => m.state === 'stopped').length;

    $('fleet-summary').textContent = data
      ? `${active} actief · ${stopped} gestopt · ${vms.length} totaal`
      : 'Wachten op meting…';

    $('fleet-cpu').replaceChildren(meter(
      'cpu', frame?.cpu,
      frame?.cpuMax ? `${fmt(frame.cpuUsed)} / ${fmt(frame.cpuMax)} vCPU` : '— vCPU',
      true,
    ));

    $('fleet-ram').replaceChildren(meter(
      'ram', frame?.ram,
      frame?.ramMax ? `${bytes(frame.ramUsed)} / ${bytes(frame.ramMax)}` : '— / —',
      true,
    ));

    $('focus-cpu').replaceChildren(focusCard('cpu', vms));
    $('focus-ram').replaceChildren(focusCard('ram', vms));
    $('fleet-chart').replaceChildren(chart('Belasting door de tijd', loadSeries, 'pct'));

    const strip = $('state-strip');
    const labels = $('state-counts');
    strip.replaceChildren();
    labels.replaceChildren();

    for (const [label, count, color] of [
      ['Actief', active, '#237966'],
      ['Gestopt', stopped, '#96a7b1'],
      ['Overig', vms.length - active - stopped, '#d89761'],
    ]) {
      const item = el('div');
      item.append(el('strong', data ? count : '—'), el('small', label));
      labels.append(item);
      strip.append(segment(vms.length ? count / vms.length : 0, color));
    }
  }

  function matchesLevel(filter, key) {
    if (!filter) return true;
    if (filter === 'high') return key === 'high';
    return key === 'high' || key === 'elevated';
  }

  function renderTable() {
    const vms = data?.vms || [];
    const q = $('search').value.trim().toLowerCase();
    const status = $('status-filter').value;
    const cpuFilter = $('cpu-filter').value;
    const ramFilter = $('ram-filter').value;
    const rows = $('rows');
    rows.replaceChildren();

    let visible = 0;

    for (const m of vms) {
      const cpu = level('cpu', m.cpu).key;
      const ram = level('ram', m.ram).key;
      const searchable = [m.id, m.name, m.node, m.raw.config?.tags].join(' ').toLowerCase();

      if (!searchable.includes(q)) continue;
      if (status === 'other' && ['running', 'stopped'].includes(m.state)) continue;
      if (status && status !== 'other' && m.state !== status) continue;
      if (!matchesLevel(cpuFilter, cpu) || !matchesLevel(ramFilter, ram)) continue;

      visible++;
      const tr = el('tr', null, cpu === 'high' || ram === 'high' ? 'hot' : '');
      const identity = el('td');
      const state = el('td');
      const action = el('td');
      const show = button('Bekijken', () => openVM(m.id));

      show.setAttribute('aria-label', `Bekijk details van ${m.name}`);
      identity.append(el('small', `VM ${m.id}`), el('strong', m.name));
      state.append(el('span', stateLabel(m.state), m.running ? 'badge running' : 'badge'));
      action.append(show);

      const ramFoot = m.running
        ? `${bytes(m.mem)} / ${bytes(m.maxmem)}`
        : `Toegewezen: ${bytes(m.maxmem)}`;

      tr.append(
        identity,
        el('td', m.node),
        state,
        metricCell('cpu', m.cpu),
        el('td', m.cpus ?? '—'),
        metricCell('ram', m.ram, ramFoot),
        el('td', m.running ? uptime(m.uptime) : '—'),
        action,
      );

      rows.append(tr);
    }

    if (!visible) {
      const tr = el('tr');
      const cell = el('td', data ? 'Geen VM’s die aan deze filters voldoen.' : 'Wachten op meting…');
      cell.colSpan = 8;
      tr.append(cell);
      rows.append(tr);
    }

    const thresholds = ['cpu', 'ram'].map(kind => {
      const [warn, high] = cfg.limits[kind];
      return `${kind.toUpperCase()}: oranje ≥ ${pct(warn)}, rood ≥ ${pct(high)}`;
    });

    $('table-foot').textContent = data
      ? `${visible} van ${vms.length} zichtbaar · ${thresholds.join(' · ')}`
      : 'Nog geen geslaagde meting.';
  }

  // ── Details van één VM ──

  function renderDetail() {
    const m = data?.vms.find(vm => vm.id === selectedId);
    $('details').hidden = !m;
    if (!m) return;

    const vm = m.raw;
    const c = vm.config || {};
    const latest = frames.at(-1)?.byId.get(m.id) || {};
    const errors = Object.keys(vm.errors || {});

    $('detail-title').textContent = m.name;
    $('detail-meta').textContent = `VM ${m.id} / ${m.node} / ${stateLabel(m.state)}`;
    $('detail-warning').hidden = errors.length === 0;
    $('detail-warning').textContent = `Niet opgehaald: ${errors.join(', ')}.`;

    $('detail-meters').replaceChildren(
      meter('cpu', m.cpu, `${m.cpus ?? '—'} vCPU toegewezen`),
      meter('ram', m.ram, m.running
        ? `${bytes(m.mem)} van ${bytes(m.maxmem)}`
        : `${bytes(m.maxmem)} toegewezen`),
    );

    const snaps = Array.isArray(vm.snapshots)
      ? vm.snapshots.filter(s => s.name !== 'current')
      : null;

    $('detail-stats').replaceChildren(
      stat('Uptime', m.running ? uptime(m.uptime) : '—'),
      stat('Schijfcapaciteit', bytes(m.maxdisk)),
      stat('Snapshots', snaps?.length ?? '—'),
    );

    $('detail-charts').replaceChildren(
      chart('CPU & RAM', loadSeries, 'pct', m.id),
      chart('Netwerkverkeer', [
        ['Ontvangen', 'netinRate', '#167567'],
        ['Verzonden', 'netoutRate', '#75609d'],
      ], 'rate', m.id),
      chart('Schijfactiviteit', [
        ['Lezen', 'diskreadRate', '#bd5428'],
        ['Schrijven', 'diskwriteRate', '#75609d'],
      ], 'rate', m.id),
    );

    $('detail-balances').replaceChildren(
      balance('Netwerkbalans', 'Ontvangen', 'Verzonden', latest.netinRate, latest.netoutRate, '#167567'),
      balance('Schijfbalans', 'Lezen', 'Schrijven', latest.diskreadRate, latest.diskwriteRate, '#bd5428'),
    );

    const disks = [];
    const adapters = [];

    for (const [key, value] of Object.entries(c)) {
      if (typeof value !== 'string') continue;
      const parts = value.split(',');
      const option = k => parts.find(p => p.startsWith(`${k}=`))?.slice(k.length + 1);

      if (/^(scsi|sata|ide|virtio)\d+$/.test(key)) {
        disks.push([key, [parts[0], option('size'), option('media')].filter(Boolean).join(' · ')]);
      }

      if (/^net\d+$/.test(key)) {
        const vlan = option('tag');
        adapters.push([key, [
          parts[0], option('bridge'), vlan ? `VLAN ${vlan}` : null,
        ].filter(Boolean).join(' · ')]);
      }
    }

    const interfaces = vm.guest_network?.result ?? vm.guest_network;
    const ips = Array.isArray(interfaces) ? interfaces.map(item => [
      item.name,
      (item['ip-addresses'] || []).map(a => a['ip-address']).filter(Boolean).join(' · '),
    ]) : [];

    const snapshotRows = (snaps || []).map(s => [
      s.name,
      [
        s.snaptime ? new Date(s.snaptime * 1000).toLocaleString('nl-BE') : null,
        s.description,
      ].filter(Boolean).join(' · ') || 'Snapshot',
    ]);

    $('detail-specs').replaceChildren(
      specs('Hardware & opstart', [
        ['CPU-model', c.cpu],
        ['Sockets', c.sockets],
        ['Cores per socket', c.cores],
        ['Besturingssysteem', c.ostype],
        ['BIOS', c.bios],
        ['Machinetype', c.machine],
        ['Bootvolgorde', c.boot],
        ['Start bij opstart', c.onboot == null ? null : Number(c.onboot) ? 'Ja' : 'Nee'],
        ['Tags', c.tags],
      ]),
      specs('I/O sinds tellerstart', [
        ['Ontvangen', bytes(m.netin)],
        ['Verzonden', bytes(m.netout)],
        ['Gelezen', bytes(m.diskread)],
        ['Geschreven', bytes(m.diskwrite)],
      ]),
      specs('Virtuele schijven', disks),
      specs('Netwerkadapters', adapters),
      specs('IP-adressen van de gast', ips),
      specs('Snapshots', snapshotRows, snaps ? 'Geen snapshots.' : 'Niet beschikbaar.'),
    );
  }

  // ── Automatisch ophalen ──

  function render() {
    renderOverview();
    renderTable();
    renderDetail();
  }

  async function update() {
    if (busy || expired) return;

    busy = true;
    clearTimeout(timer);
    $('refresh').disabled = true;

    try {
      const response = await fetch(cfg.dataUrl, {
        method: 'GET',
        mode: 'cors',
        credentials: 'omit',
        cache: 'no-store',
        headers: {
          Authorization: `Bearer ${accessToken}`,
          Accept: 'application/json',
        },
        signal: AbortSignal.timeout(180_000),
      });

      if (response.status === 401 || response.status === 403) {
        expired = true;
        throw new Error('Dashboardsessie verlopen of geweigerd. Open de pagina opnieuw.');
      }

      if (!response.ok) throw new Error(`Ophalen mislukt: HTTP ${response.status}.`);

      const body = await response.json();

      if (
        body?.data?.schema_version !== 1 ||
        !Array.isArray(body.data.vms) ||
        typeof body.token !== 'string' ||
        !body.token
      ) {
        throw new Error('Onverwachte data-uitvoer. Controleer de n8n-uitvoering.');
      }

      accessToken = body.token;
      const t = Date.parse(body.data.sampled_at);
      if (!Number.isFinite(t)) throw new Error('De meting heeft geen geldige tijdstempel.');

      if (!data || t > data.t) {
        const vms = body.data.vms.map(readVM);
        remember(vms, t);
        data = { t, vms };
        render();
      }

      $('connection').className = 'connection';
      $('connection').textContent =
        `Laatste meting: ${clock(data.t)} · Volgende aanvraag over ${seconds} seconden.`;
    } catch (error) {
      const reason = error instanceof TypeError
        ? 'Data-endpoint niet bereikbaar. Controleer de data-URL en CORS.'
        : error.message;

      const last = data ? ` Laatste geslaagde meting: ${clock(data.t)}.` : '';
      const retry = expired ? '' : ` Nieuwe poging over ${seconds} seconden.`;

      $('connection').className = 'connection warning';
      $('connection').textContent = reason + last + retry;
    } finally {
      busy = false;
      $('refresh').disabled = expired;
      if (!expired) timer = setTimeout(update, cfg.intervalMs);
    }
  }

  $('refresh').onclick = update;
  $('search').oninput = renderTable;

  for (const id of ['status-filter', 'cpu-filter', 'ram-filter']) {
    $(id).onchange = renderTable;
  }

  $('back').onclick = () => {
    selectedId = null;
    renderDetail();
    $('search').focus();
  };

  render();
  update();
}

// ── 4. Antwoord voor Dashboard tonen ────────────────────────────────────

return [{
  json: {
    html: renderDashboard(),
    responseCode: 200,
  },
}];

// n8n Code node: JavaScript, Run Once for All Items.
// Herkent de gestructureerde MCP-uitvoer en JSON in MCP-tekstblokken.
function decode(value, depth = 0) {
  if (depth > 10 || value == null) return null;
  if (typeof value === 'string') {
    try { return decode(JSON.parse(value), depth + 1); } catch { return null; }
  }
  if (typeof value !== 'object' || value.isError === true || value.error) return null;
  if (Array.isArray(value)) {
    for (const child of value) { const found = decode(child, depth + 1); if (found) return found; }
    return null;
  }
  if (value.schema_version === 1 && Array.isArray(value.vms)) return value;
  for (const key of ['structuredContent', 'content', 'text', 'result', 'data', 'output']) {
    const found = decode(value[key], depth + 1); if (found) return found;
  }
  return null;
}
let data = null;
for (const item of $('MCP - VM gegevens').all()) { data = decode(item.json); if (data) break; }
if (data) {
  // Valideer het verwachte schema; onbekende structuren worden niet als leeg cluster getoond.
  const valid = typeof data.sampled_at === 'string' && Number.isFinite(Date.parse(data.sampled_at)) &&
    data.vms.every(v => v && typeof v === 'object' && Number.isInteger(v.vmid) && typeof v.node === 'string' &&
      ['runtime','config','inventory','errors'].every(k => v[k] == null || (typeof v[k] === 'object' && !Array.isArray(v[k]))));
  if (!valid) data = null;
  else data = {schema_version:1, sampled_at:data.sampled_at, vms:data.vms.map(v => ({
    vmid:v.vmid, node:v.node, name:v.name, inventory:v.inventory || {}, runtime:v.runtime || null,
    config:v.config || null, snapshots:v.snapshots ?? null, guest_network:v.guest_network ?? null, errors:v.errors || {}
  }))};
}

const token = $input.first().json.token;
return [{json: {responseCode:data ? 200 : 502, body:data ? {data, token} : {error:'VM-gegevens konden niet worden opgehaald. Controleer MCP - VM gegevens in n8n.'}}}];
